<?php
declare(strict_types=1);
require_once __DIR__ . '/assets/php/bootstrap.php';
$userId = require_login();
if (in_array((int) ($_SESSION['role_id'] ?? 0), [3, 4], true)) redirect('backstage.php');
$s = db()->prepare('SELECT u.nom_usr,u.mail,u.dir_usr,u.fecha_creacion,COALESCE(p.alias,u.nom_usr) alias,p.biografia,p.avatar_url FROM usuario u LEFT JOIN perfil_usuario p ON p.usr_id=u.id_usr WHERE u.id_usr=:id');
$s->execute(['id'=>$userId]); $profile=$s->fetch();
if (!$profile) { session_destroy(); redirect('login.php'); }
$initial=function_exists('mb_substr')?mb_strtoupper(mb_substr($profile['alias'],0,1,'UTF-8'),'UTF-8'):strtoupper(substr($profile['alias'],0,1));
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi perfil — SIDE B</title><link rel="stylesheet" href="assets/css/variables.css"><link rel="stylesheet" href="assets/css/global.css"><link rel="stylesheet" href="assets/css/components.css"><link rel="stylesheet" href="assets/css/profile.css"></head><body><a class="skip-link" href="#contenido">Saltar al contenido</a><?=sideb_public_header('')?><main id="contenido" class="profile-page container"><div class="profile-shell"><aside class="profile-sidebar"><div class="profile-avatar" aria-hidden="true"><?php if($profile['avatar_url']):?><img src="<?=e($profile['avatar_url'])?>" alt=""><?php else:?><?=e($initial)?><?php endif;?></div><h1><?=e($profile['alias'])?></h1><p>@<?=e($profile['nom_usr'])?> · Miembro desde <?=e(date('Y',strtotime($profile['fecha_creacion'])))?></p><nav class="profile-menu" aria-label="Menú de perfil"><a class="is-active" href="perfil.php" aria-current="page">Datos personales</a><a href="guardados.php">Guardados</a><span class="profile-logout-note">Usa Cerrar sesión en la cabecera.</span></nav></aside><section class="profile-content" aria-labelledby="profile-title"><p class="eyebrow">Tu espacio en SIDE B</p><h2 id="profile-title">Mi perfil.</h2><div class="profile-grid"><div class="profile-field"><label>Nombre de usuario</label><strong><?=e($profile['nom_usr'])?></strong></div><div class="profile-field"><label>Correo electrónico</label><strong><?=e($profile['mail'])?></strong></div><div class="profile-field"><label>Alias</label><strong><?=e($profile['alias'])?></strong></div><div class="profile-field"><label>Ubicación</label><strong><?=e($profile['dir_usr'] ?: 'Sin ubicación')?></strong></div></div><?php if($profile['biografia']):?><section class="profile-section"><h3>Biografía</h3><p class="profile-note"><?=nl2br(e($profile['biografia']))?></p></section><?php endif;?></section></div></main><?=sideb_footer()?></body></html>
